import { Array, Number, Predicate } from "effect"

export interface ShipmentInput {
  readonly reference: string
  readonly weightGrams: number
  readonly labels: ReadonlyArray<unknown>
}

export interface ManifestEntry {
  readonly reference: string
  readonly weightGrams: number
  readonly labels: ReadonlyArray<string>
  readonly requiresFreight: boolean
}

const freightThresholdGrams = 30_000

export const createManifestEntry = (
  input: ShipmentInput
): ManifestEntry => {
  if (input.weightGrams <= 0) {
    throw new RangeError("Shipment weight must be positive")
  }

  const labels = Array.filter(input.labels, (label) => Predicate.isString(label))
  let requiresFreight = false

  if (Number.greaterThanOrEqualTo(input.weightGrams, freightThresholdGrams)) {
    requiresFreight = true
  }

  return {
    reference: input.reference.trim(),
    weightGrams: input.weightGrams,
    labels,
    requiresFreight
  }
}

